import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        double x = scanner.nextDouble();
        double y = scanner.nextDouble();
        int n = scanner.nextInt();

        double minDiff = 2e9;
        double aBest = 0;
        double bBest = 0;
        double ratio = x / y;

        for (int i = 1; i <= n; i++) {
            long aCandidate = (long) (ratio * i);
            double diff1 = Math.abs((double) aCandidate / i - ratio);
            double diff2 = Math.abs((double) (aCandidate + 1) / i - ratio);

            if (diff1 <= diff2 && diff1 < minDiff) {
                minDiff = diff1;
                aBest = aCandidate;
                bBest = i;
            } else if (diff2 < diff1 && diff2 < minDiff) {
                minDiff = diff2;
                aBest = aCandidate + 1;
                bBest = i;
            }
        }

        System.out.println((long) aBest + "/" + (long) bBest);
        scanner.close();
    }
}
